import React, { useEffect, useState } from 'react';
import './AddAdvertisement.css';
import AdminNav from '../../Components/AdminNav';

const API_URL = 'http://localhost:5000/advertisements';

const AddAdvertisement = () => {
  const [ads, setAds] = useState([]);
  const [form, setForm] = useState({ title: '', description: '', imageFile: null, imagePreview: null });
  const [editingId, setEditingId] = useState(null);

  const fetchAds = () => {
    fetch(API_URL)
      .then(res => res.json())
      .then(data => setAds(data))
      .catch(console.error);
  };

  useEffect(() => {
    fetchAds();
  }, []);

  const handleInputChange = e => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  const handleImageChange = e => {
    const file = e.target.files[0];
    if (file) {
      setForm(prev => ({ ...prev, imageFile: file }));
      const reader = new FileReader();
      reader.onload = () => setForm(prev => ({ ...prev, imagePreview: reader.result }));
      reader.readAsDataURL(file);
    }
  };

  const resetForm = () => {
    setForm({ title: '', description: '', imageFile: null, imagePreview: null });
    setEditingId(null);
  };

  // Convert image file to base64
  const toBase64 = file =>
    new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result.split(',')[1]); // get base64 string without mime
      reader.onerror = error => reject(error);
    });

  const handleSubmit = async e => {
    e.preventDefault();
    if (!form.title || !form.description || (!form.imageFile && !editingId)) {
      alert('Please fill title and description, and select an image for new ads.');
      return;
    }

    try {
      let endpoint = API_URL;
      let method = 'POST';
      let body;

      if (editingId) {
        // For editing (only title and description can be changed)
        endpoint = `${API_URL}/${editingId}`;
        method = 'PUT';
        body = JSON.stringify({
          title: form.title,
          description: form.description,
        });
        if (form.imageFile) {
            alert('Note: Image file change is not yet supported for editing. Only title and description will be updated.');
        }
      } else {
        // Adding new
        if (!form.imageFile) {
            alert('Please select an image file for a new advertisement.');
            return;
        }
        const base64Image = await toBase64(form.imageFile);
        body = JSON.stringify({
          title: form.title,
          description: form.description,
          base64Image,
          fileName: form.imageFile.name,
        });
      }

      const response = await fetch(endpoint, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body,
      });

      if (response.ok) {
        fetchAds();
        resetForm();
      } else {
        const err = await response.text();
        alert('Error: ' + err);
      }
    } catch (err) {
      alert('Error: ' + err.message);
    }
  };

  // FIX: Fetch full details for editing (especially description)
  const handleEdit = async id => {
    try {
        const response = await fetch(`${API_URL}/${id}`);
        if (!response.ok) {
            throw new Error('Failed to fetch ad details');
        }
        const ad = await response.json();
        setForm({ 
            title: ad.title, 
            description: ad.description, // Correctly populate description
            imageFile: null, 
            imagePreview: ad.imageUrl 
        });
        setEditingId(id);
    } catch (err) {
        alert('Error fetching ad for edit: ' + err.message);
    }
  };

  const handleDelete = async id => {
    if(window.confirm('Are you sure to delete this advertisement? This will also delete the image from storage.')) {
      try {
        const response = await fetch(`${API_URL}/${id}`, { method: 'DELETE' });
        if (response.ok) fetchAds();
        else alert('Failed to delete');
      } catch (err) {
        alert('Error: ' + err.message);
      }
    }
  };

  return (
    <div className="admin-container">
      <AdminNav/>
      <h2>{editingId ? 'Edit Advertisement' : 'Add Advertisement'}</h2>
      <form onSubmit={handleSubmit} className="admin-form">
        <input
          type="text"
          name="title"
          placeholder="Title"
          value={form.title}
          onChange={handleInputChange}
          required
        />
        <textarea
          name="description"
          placeholder="Description"
          value={form.description}
          onChange={handleInputChange}
          required
        />
        {/* The file input is not required for editing, but is required for adding new */}
        <input type="file" accept="image/*" onChange={handleImageChange} />
        {form.imagePreview && <img src={form.imagePreview} alt="preview" className="preview-image" />}
        <button type="submit">{editingId ? 'Update' : 'Add'}</button>
        {editingId && <button type="button" onClick={resetForm}>Cancel</button>}
      </form>

      <h3>Existing Advertisements</h3>
      <div className="ads-list">
        {ads.map(ad => (
          <div key={ad.id} className="ads-list-item">
            <img src={ad.imageUrl} alt={ad.title} />
            <div className="ads-list-info">
              <p><strong>{ad.title}</strong></p>
              <button onClick={() => handleEdit(ad.id)}>Edit</button>
              <button onClick={() => handleDelete(ad.id)}>Delete</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AddAdvertisement;
